o;		return true;}function showpopup(pono){        $("#myModal").modal('show');    $("#ponum").text(pono);     $("#pono").val(pono);        }</script><script>function markasapproved(i,j,itemid){        if($("#approvedrecord"+i+itemid).is(":checked"))    {        var a="1";    }else    {        var a="0";    }   	$.ajax({	type:"post",	url:"<?php echo page_url;?>Store/checktoapprovepo",	data:"id="+i+"&pono="+j+"&itemid="+itemid+"&type="+a,	success:function(data){$("#app"+i).html('Approved');$('#'+i).css({ 'background-color' : '#CCFDC1'});	}	});}																																																																				function sendmail(pono){    if($('#sendmails').is(":checked"))    {           $.ajax({																	            type:"post",            url:"<?php echo page_url;?>Store/sendemailtosupplier",            data:"pono="+pono,            success:function(data){            //	alert(data);																																																																																																																			            $("#mail"+pono).css('color','green');            $("#mail"+pono).css('font-weight','bold');            $("#mail"+pono).html('Mail Send');            }            });    }    }function checkalldata(){        if($(".appdata").is(":checked"))    {       $('input[name="approvedrecord[]"]').prop('checked',true);            }else    {        $('input[name="approvedrecord[]"]').prop('checked',false);            }    }function checkforsingleboxapproval(){  var checklen=$('[name="approvedrecord[]"]:checked').length;    if(checklen>0)    {    return true;    }else    {    alert('At least one item selection is mandatory');    return false;          }    }</script></body></html>	